Refactor this code by extracting the loop body shared by both methods:

class Report:
    def to_csv(self):
        lines = []
        for r in self.rows:
            lines.append(','.join(str(r[c]) for c in self.columns))
        return '\n'.join(lines)
    def to_tsv(self):
        lines = []
        for r in self.rows:
            lines.append('\t'.join(str(r[c]) for c in self.columns))
        return '\n'.join(lines)

output:
class Report:
    def _lines(self, delimiter):
        return [delimiter.join(str(r[c]) for c in self.columns) for r in self.rows]
    def to_csv(self):
        return '\n'.join(self._lines(','))
    def to_tsv(self):
        return '\n'.join(self._lines('\t'))

What changed: the row-formatting loop exists once as _lines(delim); the public methods now only choose a delimiter.

