def clamp_uptime(v):
    if v < 0:
        return 0
    if v > 100:
        return 100
    return v

def clamp_percent(v):
    if v < 0:
        return 0
    if v > 100:
        return 100
    return v

def clamp_latency(v):
    if v < 0:
        return 0
    return v

output:
def clamp(value, low=0, high=None):
    if value < low:
        return low
    if high is not None and value > high:
        return high
    return value

def clamp_uptime(v):
    return clamp(v, 0, 100)

def clamp_percent(v):
    return clamp(v, 0, 100)

def clamp_latency(v):
    return clamp(v, 0)

What changed: one clamp(value, low, high) helper replaced three copies of bounds logic; latency keeps its one-sided clamp via a default high.

