Refactor this code by removing the duplicated date parsing in two modules:

def parse_order_date(s):
    for fmt in ('%Y-%m-%d', '%d/%m/%Y', '%b %d %Y'):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError('bad date: ' + s)

def parse_ship_date(s):
    for fmt in ('%Y-%m-%d', '%d/%m/%Y', '%b %d %Y'):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError('bad date: ' + s)

output:
DATE_FORMATS = ('%Y-%m-%d', '%d/%m/%Y', '%b %d %Y')

def parse_any_date(s):
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError('bad date: ' + s)

def parse_order_date(s):
    return parse_any_date(s)

def parse_ship_date(s):
    return parse_any_date(s)

What changed: the format list and fallback loop exist once as parse_any_date; supported formats can be extended in one place.

