Refactor this code by unifying the two CSV readers that differ only by delimiter:

def read_commas(path):
    rows = []
    with open(path) as f:
        for line in f:
            rows.append([c.strip() for c in line.split(',')])
    return rows

def read_semicolons(path):
    rows = []
    with open(path) as f:
        for line in f:
            rows.append([c.strip() for c in line.split(';')])
    return rows

output:
def read_delimited(path, delimiter=','):
    rows = []
    with open(path) as f:
        for line in f:
            rows.append([c.strip() for c in line.split(delimiter)])
    return rows

def read_commas(path):
    return read_delimited(path, ',')

def read_semicolons(path):
    return read_delimited(path, ';')

What changed: parsing logic exists once parameterized by delimiter; a third format (tabs) is now a one-line addition.

